// Board driver for the HLS matvec kernels (contracts: hls/matvec.h, and hls4/matvec4.h with -DMATVEC4).
// See matvec_fpga.h. Buffers come from XRT (zocl, contiguous + non-cacheable on Zynq, so no cache sync is needed);
// the kernel's control registers are mapped through /dev/mem. Polling only, no interrupts.
#include "matvec_fpga.h"
#ifdef MATVEC4
#include "xmatvec4_hw.h" // generated by Vitis HLS; compile with -I../hls4
#define AP_CTRL XMATVEC4_CONTROL_ADDR_AP_CTRL
#else
#include "xmatvec_hw.h" // generated by Vitis HLS; compile with -I../hls
#define AP_CTRL XMATVEC_CONTROL_ADDR_AP_CTRL
#endif

#include <errno.h>
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <time.h>
#include <unistd.h>

#include <exception>
#include <memory>
#include <vector>

#include "xrt/xrt_bo.h"
#include "xrt/xrt_device.h"

#ifndef FPGA_REG_BASE
#define FPGA_REG_BASE 0x43C00000UL // kernel s_axilite base address in the overlay
#endif
#define REG_SIZE 0x10000UL
#define MAX_N 8192 // MATVEC_MAX_N in hls/matvec.h, MATVEC4_MAX_N in hls4/matvec4.h
#define TIMEOUT_S 5
#define CMA_ALIGN ((size_t)2 << 20) // largest alignment zocl gives CMA buffers (measured on PYNQ 3.1.1)

// Vitis HLS appends "_r" to port names that are VHDL keywords, so "out" may show up as "out_r"
#if defined(XMATVEC_CONTROL_ADDR_OUT_R_DATA)
#define ADDR_OUT XMATVEC_CONTROL_ADDR_OUT_R_DATA
#elif defined(XMATVEC_CONTROL_ADDR_OUT_DATA)
#define ADDR_OUT XMATVEC_CONTROL_ADDR_OUT_DATA
#elif defined(XMATVEC4_CONTROL_ADDR_OUT_R_DATA)
#define ADDR_OUT XMATVEC4_CONTROL_ADDR_OUT_R_DATA
#define BITS_OUT XMATVEC4_CONTROL_BITS_OUT_R_DATA
#else
#define ADDR_OUT XMATVEC4_CONTROL_ADDR_OUT_DATA
#define BITS_OUT XMATVEC4_CONTROL_BITS_OUT_DATA
#endif

static std::unique_ptr<xrt::device> dev;
static std::vector<xrt::bo> bos; // keeps every buffer (and its mapping) alive
static size_t total_bytes;
static unsigned memidx;
static volatile uint32_t *regs;
static int mem_fd = -1;
static char last_err[256]; // why the last fpga_alloc_try() failed

static inline void wr(uint32_t off, uint32_t v) { regs[off / 4] = v; }
static inline void wr64(uint32_t off, uint64_t v) { wr(off, (uint32_t)v); wr(off + 4, (uint32_t)(v >> 32)); }
static inline uint32_t rd(uint32_t off) { return regs[off / 4]; }

static inline void dsb(void) {
#if defined(__arm__) || defined(__aarch64__)
    __asm__ volatile("dsb sy" ::: "memory"); // drain the write buffer so buffer data lands before ap_start
#else
    __sync_synchronize();
#endif
}

static int open_impl(void) {
    // reading registers of an unconfigured PL hangs the CPU, so refuse early
    char st[32] = "";
    if (FILE *f = fopen("/sys/class/fpga_manager/fpga0/state", "r")) {
        if (!fgets(st, sizeof st, f)) st[0] = 0;
        fclose(f);
    }
    st[strcspn(st, "\n")] = 0;
    if (st[0] && strcmp(st, "operating")) {
        fprintf(stderr, "fpga: PL is not configured (fpga_manager state '%s'); load the overlay first\n", st);
        return -1;
    }

    if (const char *e = getenv("FPGA_MEMIDX")) {
        char *end;
        long v = strtol(e, &end, 0);
        if (!*e || *end || v < 0) {
            fprintf(stderr, "fpga: bad FPGA_MEMIDX '%s'\n", e);
            return -1;
        }
        memidx = (unsigned)v;
    }

    mem_fd = open("/dev/mem", O_RDWR | O_SYNC);
    if (mem_fd < 0) {
        fprintf(stderr, "fpga: cannot open /dev/mem (run as root): %s\n", strerror(errno));
        return -1;
    }
    void *m = mmap(NULL, REG_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, mem_fd, FPGA_REG_BASE);
    if (m == MAP_FAILED) {
        fprintf(stderr, "fpga: cannot map registers at 0x%lx: %s\n", (unsigned long)FPGA_REG_BASE, strerror(errno));
        return -1;
    }
    regs = (volatile uint32_t *)m;

    try {
        dev.reset(new xrt::device(0));
    } catch (const std::exception &e) {
        fprintf(stderr, "fpga: cannot open XRT device 0 (needs root and a loaded overlay): %s\n", e.what());
        return -1;
    }

    uint32_t c = rd(AP_CTRL); // also clears a stale ap_done
    if (!(c & 4)) fprintf(stderr, "fpga: warning: kernel not idle at open (AP_CTRL=0x%x)\n", c);
    return 0;
}

int fpga_open(void) {
    if (regs) return 0;
    if (open_impl()) {
        fpga_close();
        return -1;
    }
    return 0;
}

void *fpga_alloc_try(size_t bytes, uint64_t *phys) {
    if (!dev || !bytes) {
        snprintf(last_err, sizeof last_err, "%s", dev ? "zero size" : "fpga_open() not called");
        return NULL;
    }
    // zocl allocates from CMA, aligning each buffer up to 2 MiB; a hole left behind by a size that is not a
    // multiple of that can only be filled by smaller buffers. Rounding big buffers up lets them tile CMA.
    size_t size = bytes < CMA_ALIGN ? bytes : (bytes + CMA_ALIGN - 1) & ~(CMA_ALIGN - 1);
    try {
        xrt::bo bo(*dev, size, xrt::bo::flags::normal, memidx);
        void *p = bo.map<void *>();
        *phys = bo.address();
        bos.push_back(bo);
        total_bytes += size;
        return p;
    } catch (const std::exception &e) {
        snprintf(last_err, sizeof last_err,
                 "%zu bytes on memidx %u failed after %.1f MiB already allocated "
                 "(contiguous CMA memory exhausted or fragmented, or wrong FPGA_MEMIDX?): %s",
                 bytes, memidx, total_bytes / 1048576.0, e.what());
        return NULL;
    }
}

void *fpga_alloc(size_t bytes, uint64_t *phys) {
    void *p = fpga_alloc_try(bytes, phys);
    if (!p) fprintf(stderr, "fpga_alloc: %s\n", last_err);
    return p;
}

// start the kernel and poll ap_done: 0, or -1 after TIMEOUT_S; *ctrl gets the last AP_CTRL value
static int run_kernel(uint32_t *ctrl) {
    dsb();
    wr(AP_CTRL, 1); // ap_start

    struct timespec t0, t;
    clock_gettime(CLOCK_MONOTONIC, &t0);
    for (unsigned i = 1; !((*ctrl = rd(AP_CTRL)) & 2); i++) { // ap_done, clear-on-read
        if (i % 1024) continue;
        clock_gettime(CLOCK_MONOTONIC, &t);
        if (t.tv_sec - t0.tv_sec >= TIMEOUT_S) return -1;
    }
    dsb(); // result reads must not be reordered before the done read
    return 0;
}

#ifndef MATVEC4
int fpga_matvec(uint64_t wq, uint64_t ws, uint64_t xq, uint64_t xs, uint64_t out, int n, int d, int gs) {
    if (!regs) {
        fprintf(stderr, "fpga_matvec: fpga_open() not called\n");
        return -1;
    }
    if ((gs != 32 && gs != 64) || n <= 0 || n > MAX_N || n % gs || d <= 0) {
        fprintf(stderr, "fpga_matvec: unsupported n=%d d=%d gs=%d (need gs 32 or 64, n %% gs == 0, n <= %d)\n",
                n, d, gs, MAX_N);
        return -1;
    }
    wr64(XMATVEC_CONTROL_ADDR_WQ_DATA, wq);
    wr64(XMATVEC_CONTROL_ADDR_WS_DATA, ws);
    wr64(XMATVEC_CONTROL_ADDR_XQ_DATA, xq);
    wr64(XMATVEC_CONTROL_ADDR_XS_DATA, xs);
    wr64(ADDR_OUT, out);
    wr(XMATVEC_CONTROL_ADDR_N_DATA, (uint32_t)n);
    wr(XMATVEC_CONTROL_ADDR_D_DATA, (uint32_t)d);
    wr(XMATVEC_CONTROL_ADDR_GS_DATA, (uint32_t)gs);
    uint32_t c;
    if (run_kernel(&c)) {
        fprintf(stderr, "fpga_matvec: kernel did not finish in %d s (AP_CTRL=0x%x, n=%d d=%d gs=%d)\n",
                TIMEOUT_S, c, n, d, gs);
        return -1;
    }
    return 0;
}
#else
// pointer registers are 32 or 64 bits wide, depending on the address width the kernel was synthesized with
static void wr_ptr(uint32_t off, int bits, uint64_t v) {
    if (bits == 64) wr64(off, v);
    else wr(off, (uint32_t)v);
}
#define WR_PTR(name, v) wr_ptr(XMATVEC4_CONTROL_ADDR_##name##_DATA, XMATVEC4_CONTROL_BITS_##name##_DATA, v)

int fpga_matvec4(uint64_t w, uint64_t ws, uint64_t xq, uint64_t xs, uint64_t out, int n, int d, int wbits) {
    if (!regs) {
        fprintf(stderr, "fpga_matvec4: fpga_open() not called\n");
        return -1;
    }
    if ((wbits != 4 && wbits != 8) || n <= 0 || n > MAX_N || n % 32 || d <= 0 || ((w | ws | xq | xs | out) & 63)) {
        fprintf(stderr, "fpga_matvec4: unsupported n=%d d=%d wbits=%d or a buffer not 64-byte aligned "
                "(need wbits 4 or 8, n %% 32 == 0, n <= %d)\n", n, d, wbits, MAX_N);
        return -1;
    }
    WR_PTR(W, w);
    WR_PTR(WS, ws);
    WR_PTR(XQ, xq);
    WR_PTR(XS, xs);
    wr_ptr(ADDR_OUT, BITS_OUT, out);
    wr(XMATVEC4_CONTROL_ADDR_N_DATA, (uint32_t)n);
    wr(XMATVEC4_CONTROL_ADDR_D_DATA, (uint32_t)d);
    wr(XMATVEC4_CONTROL_ADDR_WBITS_DATA, (uint32_t)wbits);
    uint32_t c;
    if (run_kernel(&c)) {
        fprintf(stderr, "fpga_matvec4: kernel did not finish in %d s (AP_CTRL=0x%x, n=%d d=%d wbits=%d)\n",
                TIMEOUT_S, c, n, d, wbits);
        return -1;
    }
    return 0;
}
#endif

void fpga_close(void) {
    if (regs) munmap((void *)regs, REG_SIZE);
    regs = NULL;
    if (mem_fd >= 0) close(mem_fd);
    mem_fd = -1;
    bos.clear();
    dev.reset();
    total_bytes = 0;
}
